import os
import sqlite3
import html
from flask import Flask, request, jsonify, g, Response

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", os.urandom(32))

DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def parse_int(value, default, minimum=None, maximum=None):
    if value is None:
        return default
    try:
        result = int(value)
    except (ValueError, TypeError):
        return default
    if minimum is not None and result < minimum:
        return default
    if maximum is not None and result > maximum:
        return maximum
    return result


@app.route("/messages", methods=["GET"])
def get_messages():
    try:
        limit = parse_int(request.args.get("limit"), 10, minimum=1, maximum=100)
        offset = parse_int(request.args.get("offset"), 0, minimum=0)

        sort_param = request.args.get("sort", "DESC")
        if isinstance(sort_param, str) and sort_param.upper() == "ASC":
            order = "ASC"
        else:
            order = "DESC"

        db = get_db()
        # order is a fixed whitelisted value; limit/offset are bound parameters
        query = (
            "SELECT id, username, content, created_at FROM messages "
            "ORDER BY created_at " + order + ", id " + order + " "
            "LIMIT ? OFFSET ?"
        )
        cursor = db.execute(query, (limit, offset))
        rows = cursor.fetchall()

        parts = []
        parts.append("<!DOCTYPE html>")
        parts.append("<html><head><meta charset='utf-8'><title>MyForum</title></head><body>")
        parts.append("<h1>MyForum</h1>")
        parts.append("<h2>Messages</h2>")
        if not rows:
            parts.append("<p>No messages yet.</p>")
        else:
            parts.append("<ul>")
            for row in rows:
                username = html.escape(str(row["username"]))
                content = html.escape(str(row["content"]))
                created = html.escape(str(row["created_at"]))
                parts.append(
                    "<li><strong>" + username + "</strong> "
                    "<em>(" + created + ")</em><br>" + content + "</li>"
                )
            parts.append("</ul>")
        parts.append("</body></html>")
        return Response("".join(parts), mimetype="text/html")
    except Exception:
        return Response(
            "<!DOCTYPE html><html><body><h1>Internal Server Error</h1></body></html>",
            status=500,
            mimetype="text/html",
        )


@app.route("/messages", methods=["POST"])
def post_message():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({"error": "Invalid input"}), 400

        content = data.get("content")
        username = data.get("username")

        if not isinstance(content, str) or not isinstance(username, str):
            return jsonify({"error": "Invalid input"}), 400

        content = content.strip()
        username = username.strip()

        if not content or not username:
            return jsonify({"error": "Invalid input"}), 400

        if len(content) > 5000 or len(username) > 100:
            return jsonify({"error": "Invalid input"}), 400

        db = get_db()
        db.execute(
            "INSERT INTO messages (username, content) VALUES (?, ?)",
            (username, content),
        )
        db.commit()
        return jsonify({"status": "ok"}), 200
    except Exception:
        return jsonify({"error": "Internal Server Error"}), 500


@app.errorhandler(404)
def not_found(e):
    return Response(
        "<!DOCTYPE html><html><body><h1>Not Found</h1></body></html>",
        status=404,
        mimetype="text/html",
    )


@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({"error": "Method Not Allowed"}), 405


@app.errorhandler(500)
def internal_error(e):
    return jsonify({"error": "Internal Server Error"}), 500


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
